<script setup lang="ts">
import { computed, onMounted, ref, shallowRef, watch } from 'vue';
import type { ReplayDocument, ReplayEvent, ScriptSnapshot } from '../shared/domain/contracts.js';
import { defaultScriptText, importScript, type ScriptImport } from '../shared/import/script.js';
import { BASE_COUNTS, createReplay, type SetupPlayer } from '../shared/domain/setup.js';
import { projectReplay } from '../shared/domain/projection.js';
import { presentReplay } from '../shared/presentation/from-domain.js';
import ReplayView from '../shared/presentation/ReplayView.vue';
import { TEAM_LABELS, copyJson } from '../shared/roles/editor-model.js';
import RecordComposer from './RecordComposer.vue';
import { advancePhase, appendRecordedEvent, buildRecordedEvent, newEventDraft, newEffectDraft, type EventDraft } from '../shared/domain/recording.js';
import { auditRevision,previewHistory,type RevisionPreview } from '../shared/domain/history.js';
import { parseStrictJson } from '../shared/import/script.js';

const rows=ref<{replayId:string;title:string;revision:number;events:number}[]>([]), current=ref<ReplayDocument>();
const screen=ref<'list'|'setup'|'editor'>('list'),error=ref(''),message=ref(''),busy=ref(false);
const sourceText=ref(''),preview=ref<ScriptImport>(),script=ref<ScriptSnapshot>();
const title=ref('我的对局复盘'),count=ref(12),players=ref<SetupPlayer[]>([]),setupNotes=ref(''),dirty=ref(false);
const presentation=computed(()=>current.value?presentReplay(copyJson(current.value)):undefined);
const draftKey='botcreplay-replay-draft-v1';
const composer=ref<InstanceType<typeof RecordComposer>>();
const state=computed(()=>current.value?projectReplay(copyJson(current.value)).state:undefined);
const latestPhase=computed(()=>current.value?.phases.at(-1));
const nightOrder=ref<string[]>([]);
const editing=ref<ReplayEvent>(),reason=ref(''),revision=ref<RevisionPreview>(),cascade=ref(false),undo=shallowRef<ReplayDocument[]>([]),redo=shallowRef<ReplayDocument[]>([]);
const restoreId=ref(''),restoreVersions=ref<number[]>([]),restoreVersion=ref<number>();
const historyPage=ref(1);
const orderedEvents=computed(()=>current.value?[...current.value.events].sort((a,b)=>(current.value!.phases.find(phase=>phase.phaseId===a.phaseId)!.order-current.value!.phases.find(phase=>phase.phaseId===b.phaseId)!.order)||a.order-b.order):[]);
const historyRows=computed(()=>orderedEvents.value.slice((historyPage.value-1)*50,historyPage.value*50));
const composerState=computed(()=>editing.value&&current.value?projectReplay(copyJson(current.value)).events.find(event=>event.eventId===editing.value!.eventId)?.before??state.value:state.value);
const nightEntrances=computed(()=>{if(!current.value||!state.value||latestPhase.value?.kind!=='night')return [];const key=latestPhase.value.number===1?'firstNight':'otherNight';return state.value.abilities.map(ability=>{const holder=ability.holder;const player=holder.kind==='player'?state.value!.players.find(player=>player.playerId===holder.playerId):undefined;const entry=current.value!.script.roles.find(item=>item.role.roleId===ability.rule.roleId);return {ability,player,order:Number(entry?.raw[key]??0)};}).filter(item=>item.player&&(item.player.life.actuallyAlive||item.ability.deathAccess==='retained')&&item.ability.usage.state!=='lost'&&item.ability.usage.state!=='consumed'&&item.order>0).sort((a,b)=>{const ai=nightOrder.value.indexOf(a.ability.abilityInstanceId),bi=nightOrder.value.indexOf(b.ability.abilityInstanceId);return ai>=0||bi>=0?(ai<0?1e6:ai)-(bi<0?1e6:bi):a.order-b.order;});});
const draftAvailable=ref(!!localStorage.getItem(draftKey));
const conditionLabel=(kind:string)=>({drunk:'醉酒',poisoned:'中毒','zombuul-alive':'活尸','falsely-dead':'假死',registration:'特殊识别'}[kind]??kind);
function playerIcon(assetId?:string){const asset=current.value?.assets.find(asset=>asset.assetId===assetId);return asset?.status==='cached'&&asset.contentHash?'/api/assets/'+asset.contentHash:undefined;}
const phaseLabel=(phase:ReplayDocument['phases'][number])=>phase.kind==='preparation'?'准备':`第${phase.number}${phase.kind==='night'?'夜':'天'}`;
async function api<T>(path:string,method='GET',body?:unknown):Promise<T> { const response=await fetch(path,{method,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined}); const value=await response.json(); if(!response.ok) throw new Error(value.error??'本地服务操作失败'); return value; }
async function act(fn:()=>Promise<void>) { error.value='';message.value='';busy.value=true;try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;} }
async function refresh() { rows.value=await api('/api/replays'); }
async function open(id:string) { await act(async()=>{current.value=await api('/api/replays/'+id);screen.value='editor';dirty.value=false;}); }
function previewImport(){preview.value=importScript(sourceText.value);}
function acceptScript() { if(preview.value?.script){script.value=preview.value.script;defaultSeats();} }
function defaultSeats(){ if(!script.value) return; const ordered=Object.keys(TEAM_LABELS).flatMap((team,i)=>script.value!.roles.filter(item=>item.role.type===team).slice(0,BASE_COUNTS[count.value]![i])); players.value=Array.from({length:count.value},(_,i)=>({nickname:`${i+1}号玩家`,roleId:ordered[i]?.role.roleId??script.value!.roles[i%script.value!.roles.length]!.role.roleId,alignment:ordered[i]?.role.type==='minion'||ordered[i]?.role.type==='demon'?'evil':'good'})); }
watch(count,defaultSeats);
function begin(){screen.value='setup';sourceText.value='';preview.value=undefined;script.value=undefined;error.value='';message.value='';}
function defaults(){sourceText.value=defaultScriptText();previewImport();acceptScript();}
async function readFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(file){if(file.size>16*1024*1024){error.value='剧本文件超过16MiB';return;}sourceText.value=await file.text();previewImport();}}
async function clipboard(){try{sourceText.value=await navigator.clipboard.readText();previewImport();}catch{error.value='无法读取剪贴板，请粘贴文本或选择JSON文件。';}}
async function create(){await act(async()=>{if(!script.value)throw Error('请先预览并采用剧本');const document=createReplay(copyJson(script.value),{replayId:crypto.randomUUID(),title:title.value,players:copyJson(players.value),notes:setupNotes.value});current.value=await api('/api/replays','POST',{document});screen.value='editor';dirty.value=false;message.value='整局已保存，可进入首夜。';await refresh();});}
async function save(){await act(async()=>{if(!current.value)return;const saved=await api<ReplayDocument>('/api/replays/'+current.value.replayId,'PUT',{document:current.value,expectedRevision:current.value.revision});current.value=saved;dirty.value=false;localStorage.removeItem(draftKey);draftAvailable.value=false;message.value=`已保存修订 ${saved.revision}`;await refresh();});}
async function cache(){await act(async()=>{if(!current.value)return;if(dirty.value)throw Error('请先保存整局，再缓存图标');const saved=await api<ReplayDocument>('/api/replays/'+current.value.replayId+'/cache','POST',{expectedRevision:current.value.revision,retry:true});current.value=saved;message.value=`图标缓存完成：${saved.assets.filter(asset=>asset.status==='cached').length}成功，${saved.assets.filter(asset=>asset.status!=='cached').length}使用占位；可再次重试。`;});}
function restoreDraft(){try{const document=JSON.parse(localStorage.getItem(draftKey)??'null');projectReplay(document);current.value=document;screen.value='editor';dirty.value=true;message.value='已恢复本机草稿，保存时将检查版本冲突。';}catch{error.value='草稿无法校验，请先下载草稿保留原始内容。';}}
function download(data:string,name:string,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const anchor=document.createElement('a');anchor.href=url;anchor.download=name;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function draftDownload(){download(localStorage.getItem(draftKey)??'{}','BOTCreplay-草稿.json');}
function discardDraft(){localStorage.removeItem(draftKey);draftAvailable.value=false;}
async function persistCandidate(candidate:ReplayDocument,text:string,track=true){if(!current.value)return;const before=copyJson(current.value);candidate.revision=before.revision;const saved=await api<ReplayDocument>('/api/replays/'+candidate.replayId,'PUT',{document:candidate,expectedRevision:before.revision});if(track){undo.value.push(before);if(undo.value.length>30)undo.value.shift();redo.value=[];}current.value=saved;dirty.value=false;message.value=`${text} · 已保存修订 ${saved.revision}`;}
async function nextPhase(){await act(async()=>{if(!current.value)return;await persistCandidate(advancePhase(copyJson(current.value)),'阶段已推进');nightOrder.value=[];});}
async function record(draft:EventDraft){await act(async()=>{if(!current.value)return;if(editing.value){const base=copyJson(current.value),without={...base,events:base.events.filter(event=>event.eventId!==editing.value!.eventId)};const replacement=buildRecordedEvent(without,draft,copyJson(composerState.value!));replacement.order=editing.value.order;revision.value=previewHistory(base,base.events.map(event=>event.eventId===editing.value!.eventId?replacement:event),reason.value);message.value='修订候选已准备，请查看影响并应用。';return;}const candidate=appendRecordedEvent(copyJson(current.value),draft);await persistCandidate(candidate,'记录已保存');composer.value?.clear();});}
function editEvent(event:ReplayEvent){editing.value=copyJson(event);reason.value='';revision.value=undefined;setTimeout(()=>document.querySelector('.record-composer')?.scrollIntoView({behavior:'smooth'}),0);}
function cancelEdit(){editing.value=undefined;revision.value=undefined;}
async function applyRevision(){await act(async()=>{if(!current.value||!revision.value?.candidate)return;if(revision.value.baseRevision!==current.value.revision)throw Error('预览后版本已经改变，请重新预览修订影响');await persistCandidate(auditRevision(copyJson(revision.value.candidate),revision.value.reason,current.value.revision),'历史修订已保存');cancelEdit();composer.value?.clear();});}
function deleteEvent(event:ReplayEvent){try{if(!current.value)return;revision.value=previewHistory(copyJson(current.value),copyJson(current.value.events.filter(item=>item.eventId!==event.eventId)),reason.value,cascade.value);}catch(caught){error.value=(caught as Error).message;}}
function moveEvent(event:ReplayEvent,offset:number){try{if(!current.value)return;const events=copyJson(current.value.events),group=events.filter(item=>item.phaseId===event.phaseId).sort((a,b)=>a.order-b.order),index=group.findIndex(item=>item.eventId===event.eventId),other=group[index+offset];if(!other)return;const old=events.find(item=>item.eventId===event.eventId)!;[old.order,other.order]=[other.order,old.order];revision.value=previewHistory(copyJson(current.value),events,reason.value);}catch(caught){error.value=(caught as Error).message;}}
async function undoRedo(direction:'undo'|'redo'){await act(async()=>{if(!current.value)return;const from=direction==='undo'?undo:redo,to=direction==='undo'?redo:undo;const candidate=from.value.at(-1);if(!candidate)return;const before=copyJson(current.value);await persistCandidate(copyJson(candidate),direction==='undo'?'已撤销（新修订）':'已恢复（新修订）',false);from.value.pop();to.value.push(before);cancelEdit();});}
async function showRecovery(id:string){await act(async()=>{restoreId.value=id;restoreVersions.value=await api('/api/replays/'+id+'/history');restoreVersion.value=restoreVersions.value[0];message.value=restoreVersions.value.length?'请选择恢复版本，副本会保留原文件。':'暂无恢复版本，可导入整局资源备份。';});}
async function recoverVersion(){await act(async()=>{current.value=await api('/api/replays/restore-version','POST',{replayId:restoreId.value,revision:restoreVersion.value});screen.value='editor';restoreId.value='';message.value='已创建恢复副本，原复盘文件保留。';await refresh();});}
async function backup(){await act(async()=>{if(!current.value)return;const value=await api('/api/replays/'+current.value.replayId+'/backup?revision='+current.value.revision);download(JSON.stringify(value,null,2),`${current.value.title}-r${current.value.revision}.botcreplay.json`);message.value='整局与可用图标已打包为可编辑JSON备份。';});}
async function importBackup(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await act(async()=>{if(file.size>128*1024*1024)throw Error('备份超过128MiB');const parsed=parseStrictJson(await file.text());if(parsed.errors.length)throw Error('备份JSON无效：'+parsed.errors[0].message);current.value=await api('/api/replays/restore','POST',{backup:parsed.value});screen.value='editor';message.value='备份已导入为新副本。';await refresh();});}
async function quickLife(playerId:string){if(!current.value||!state.value)return;const player=state.value.players.find(player=>player.playerId===playerId)!;const draft=newEventDraft(current.value.phases.at(-1)!.phaseId,playerId);draft.action=player.life.actuallyAlive?'实际死亡':'实际复活';draft.text=`${player.nickname}由说书人记录${player.life.actuallyAlive?'实际死亡':'实际复活'}。`;draft.effects=[newEffectDraft(player.life.actuallyAlive?'death':'revive',playerId)];await record(draft);}
function moveNight(index:number,offset:number){const ids=nightEntrances.value.map(item=>item.ability.abilityInstanceId),to=index+offset;if(to<0||to>=ids.length)return;[ids[index],ids[to]]=[ids[to]!,ids[index]!];nightOrder.value=ids;}
async function saveNight(){if(!current.value)return;const draft=newEventDraft(current.value.phases.at(-1)!.phaseId);draft.action='夜序提示';draft.hintOrder=nightEntrances.value.map(item=>item.ability.abilityInstanceId);draft.text='本夜手动提示顺序：'+nightEntrances.value.map(item=>`${item.player!.nickname}（${item.ability.rule.roleName} · ${item.ability.mode==='real'?'真实':'认知'}）`).join(' → ');draft.note='仅改变提示顺序，既有事实顺序保持。';await record(draft);}
watch(()=>[current.value?.replayId,current.value?.phases.at(-1)?.phaseId],()=>{const last=current.value?.events.filter(event=>event.phaseId===latestPhase.value?.phaseId&&event.action.name==='夜序提示').at(-1);nightOrder.value=Array.isArray(last?.action.input.hintOrder)?last!.action.input.hintOrder as string[]:[];});
watch(()=>current.value?.replayId,()=>{undo.value=[];redo.value=[];cancelEdit();historyPage.value=1;});
watch(current,()=>{if(dirty.value&&current.value){try{localStorage.setItem(draftKey,JSON.stringify(current.value));draftAvailable.value=true;}catch{error.value='浏览器草稿存储已满，请保存或下载草稿。';}}},{deep:true});
onMounted(()=>void act(refresh));
</script>
<template>
  <section class="game-shell">
    <header class="game-head"><div><span class="eyebrow">BOTCREPLAY · 整局工作区</span><h1>把每个夜晚，留在时间里</h1><p>导入剧本，准备座位，记录说书人的实际裁决。</p></div><button @click="begin" :disabled="busy">＋ 新建复盘</button></header>
    <p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p>
    <p v-if="busy" class="notice" role="status">正在处理，请保留此页面…</p>
    <div v-if="draftAvailable" class="draft-bar">有本机未保存草稿 <button @click="restoreDraft">恢复草稿</button><button @click="draftDownload">下载草稿</button><button @click="discardDraft">清除草稿</button></div>
    <section v-if="screen==='list'" class="panel"><h2>本地复盘 <small>{{rows.length}} 局</small></h2><label class="file-button">导入整局资源备份<input type="file" accept=".json" @change="importBackup"></label><p v-if="!rows.length">从一份剧本开始。整局数据保存在本机，可随时继续。</p><div class="replay-list"><div v-for="row in rows" :key="row.replayId" class="replay-item"><button @click="open(row.replayId)"><strong>{{row.title}}</strong><span>{{row.events}} 条记录 · 修订 {{row.revision}}</span></button><button @click="showRecovery(row.replayId)">恢复版本</button></div></div></section>
    <section v-if="restoreId" class="panel"><h2>从本机恢复版本创建副本</h2><p>原文件与旧修订均保留，适用于恢复误操作或损坏文件。</p><label>恢复修订<select v-model="restoreVersion"><option v-for="version in restoreVersions" :key="version" :value="version">修订 {{version}}</option></select></label><div class="toolbar"><button @click="recoverVersion" :disabled="!restoreVersion||busy">创建恢复副本</button><button @click="restoreId=''">关闭</button></div></section>
    <template v-if="screen==='setup'">
      <section class="panel"><h2>1 · 导入剧本</h2><div class="toolbar"><button @click="defaults">使用默认角色库</button><button @click="clipboard">读取剪贴板</button><label class="file-button">选择JSON文件<input type="file" accept=".json,application/json" @change="readFile"></label></div>
      <label>剧本JSON原文<textarea v-model="sourceText" rows="7" placeholder="粘贴角色数组"></textarea></label><button @click="previewImport">校验并预览</button>
      <div v-if="preview"><p>{{preview.script?.roles.length??0}} 个可用角色 · {{preview.errors.length}} 个错误 · {{preview.warnings.length}} 个提示</p><ul class="import-issues"><li v-for="(issue,index) in preview.errors" :key="'e'+index" class="error">{{issue.path}} {{issue.line?`第${issue.line}行第${issue.column}列`:''}} {{issue.message}}</li><li v-for="(issue,index) in preview.warnings" :key="'w'+index">{{issue.path}} {{issue.message}}</li></ul><div class="role-chips"><span v-for="item in preview.script?.roles" :key="item.role.roleId">{{item.role.name}}</span></div><button :disabled="!preview.script" @click="acceptScript">采用预览剧本</button></div></section>
      <section v-if="script" class="panel"><h2>2 · 准备座位</h2><div class="setup-options"><label>复盘名称<input v-model="title"></label><label>玩家人数<select v-model="count"><option v-for="n in 9" :key="n" :value="n+6">{{n+6}} 人</option></select></label><button @click="defaultSeats">按基础数量推荐分配</button></div><p>基础推荐：{{BASE_COUNTS[count]?.join(' / ')}}（镇民 / 外来者 / 爪牙 / 恶魔）。实际配版以填写为准。</p>
      <div class="setup-table"><div v-for="(player,index) in players" :key="index" class="setup-row"><strong>{{index+1}}号</strong><label>昵称<input v-model="player.nickname" :aria-label="`${index+1}号昵称`"></label><label>实际角色<select v-model="player.roleId" :aria-label="`${index+1}号实际角色`"><option v-for="item in script.roles" :key="item.role.roleId" :value="item.role.roleId">{{item.role.name}} · {{TEAM_LABELS[item.role.type]}}</option></select></label><label>当前实际阵营<select v-model="player.alignment" :class="player.alignment" :aria-label="`${index+1}号阵营`"><option value="good">善良</option><option value="evil">邪恶</option></select></label><label>认知角色<select v-model="player.perceivedRoleId" :aria-label="`${index+1}号认知角色`"><option :value="undefined">无覆盖</option><option v-for="item in script.roles" :key="item.role.roleId" :value="item.role.roleId">{{item.role.name}}</option></select></label><label>伪装角色<select v-model="player.disguiseRoleId"><option :value="undefined">无</option><option v-for="item in script.roles" :key="item.role.roleId" :value="item.role.roleId">{{item.role.name}}</option></select></label></div></div>
      <label>设置关系、配版调整与准备说明<textarea v-model="setupNotes" placeholder="与基础数量不同、同角色多人、认知覆盖来源或特殊设置时写明依据"></textarea></label><button :disabled="busy" @click="create">保存准备 · 创建整局</button></section>
    </template>
    <template v-if="screen==='editor'&&current">
      <section class="panel"><div class="toolbar"><button @click="screen='list';refresh()">← 本地复盘</button><strong>{{current.title}} · 修订 {{current.revision}}</strong><button @click="save" :disabled="busy">保存整局</button><button @click="cache" :disabled="busy">缓存 / 重试剧本图标</button><button @click="nextPhase" :disabled="busy">{{latestPhase?.kind==='preparation'?'进入首夜':latestPhase?.kind==='night'?'进入白天':'进入下一夜'}}</button></div><p>当前阶段：{{phaseLabel(current.phases.at(-1)!)}} · {{current.initialState.players.length}} 人 · {{current.events.length}} 条记录</p><p class="muted">图标按需缓存到本机，下载失败保留角色文字与占位。</p></section>
      <section v-if="state" class="panel"><h2>当前座位 · {{phaseLabel(current.phases.at(-1)!)}}</h2><div class="seat-ring"><div class="ring-center"><strong>{{state.players.length}}人</strong><span>{{phaseLabel(current.phases.at(-1)!)}}</span></div><div v-for="(player,index) in state.players" :key="player.playerId" class="ring-seat" :class="{dead:!player.life.actuallyAlive}" :style="{left:`${50+42*Math.sin(2*Math.PI*index/state.players.length)}%`,top:`${50-42*Math.cos(2*Math.PI*index/state.players.length)}%`}"><img v-if="playerIcon(player.actualRole.iconAssetId)" class="seat-icon" :src="playerIcon(player.actualRole.iconAssetId)" :alt="player.actualRole.name"><span v-else class="seat-icon seat-placeholder" aria-label="图标未缓存">?</span><strong :class="player.alignment">{{player.seat}} · {{player.nickname}}</strong><span :class="player.alignment">{{player.actualRole.name}} · {{player.alignment==='good'?'善良':'邪恶'}}</span><small v-if="player.perceivedRole">认知：{{player.perceivedRole.name}}</small><small>{{state.conditions.filter(item=>item.targetPlayerId===player.playerId&&item.active).map(item=>conditionLabel(item.kind)).join(' / ')}}</small><button :disabled="busy" @click="quickLife(player.playerId)" :aria-label="`${player.seat}号${player.life.actuallyAlive?'记录死亡':'记录复活'}`">{{player.life.actuallyAlive?'存活 → 记录死亡':'💀 死亡 → 复活'}}</button></div></div></section>
      <section v-if="latestPhase?.kind==='night'" class="panel"><h2>本夜提示顺序</h2><p class="muted">按剧本夜序与在场真实/认知能力提示，可人工调整；死亡触发仍从记录入口关联来源。</p><ol class="night-list"><li v-for="(item,index) in nightEntrances" :key="item.ability.abilityInstanceId"><span>{{item.player!.seat}}号 {{item.player!.nickname}} · {{item.ability.rule.roleName}}（{{item.ability.mode==='real'?'真实':'认知'}}）</span><button @click="moveNight(index,-1)" :disabled="index===0">上移</button><button @click="moveNight(index,1)" :disabled="index===nightEntrances.length-1">下移</button></li></ol><button @click="saveNight" :disabled="busy">保存本夜提示顺序</button></section>
      <section class="panel history-panel"><h2>历史、修订与备份</h2><div class="toolbar"><button @click="undoRedo('undo')" :disabled="!undo.length||busy">撤销上次修改</button><button @click="undoRedo('redo')" :disabled="!redo.length||busy">恢复撤销</button><button @click="showRecovery(current.replayId)">查看本机恢复版本</button><button @click="backup" :disabled="busy">下载整局资源备份</button></div><label>历史修订原因<input v-model="reason" aria-label="历史修订原因" placeholder="编辑、重排、删除历史前填写原因"></label><label class="inline-label"><input type="checkbox" v-model="cascade">删除时同时预览删除关联依赖记录</label><div class="history-list"><div v-for="event in historyRows" :key="event.eventId" class="history-row"><span>{{phaseLabel(current.phases.find(phase=>phase.phaseId===event.phaseId)!)}} · {{event.action.name}} · {{event.eventId.slice(0,8)}}</span><button @click="editEvent(event)" :aria-label="'编辑记录'+event.eventId">编辑</button><button @click="moveEvent(event,-1)">上移</button><button @click="moveEvent(event,1)">下移</button><button @click="deleteEvent(event)" :aria-label="'删除记录'+event.eventId">删除预览</button></div></div><div class="toolbar"><button :disabled="historyPage===1" @click="historyPage--">上一页</button><span>{{historyPage}} / {{Math.max(1,Math.ceil(orderedEvents.length/50))}}</span><button :disabled="historyPage*50>=orderedEvents.length" @click="historyPage++">下一页</button></div>
      <div v-if="revision" class="revision-preview" role="status"><strong>修订影响预览</strong><p>删除{{revision.removedIds.length}}条；{{revision.changedSnapshotIds.length}}条事件时状态变化；{{revision.unchangedInformation}}条既有信息保持。原因：{{revision.reason}}</p><p v-if="revision.removedIds.length">将删除：{{revision.removedIds.join('、')}}</p><p v-if="revision.error" class="error">无法应用：{{revision.error}}。请修正后续引用或选择同时删除依赖，不自动改写已收到的信息。</p><div class="toolbar"><button @click="applyRevision" :disabled="!revision.candidate||busy">应用此修订</button><button @click="revision=undefined">放弃预览</button></div></div></section>
      <RecordComposer v-if="composerState" ref="composer" :document="current" :state="composerState" :editing="editing" :busy="busy" @record="record" @cancel="cancelEdit" />
      <ReplayView v-if="presentation" :replay="presentation" />
    </template>
  </section>
</template>
